export const BODY: string = "\n<p>السطوع والتعريض والتباين هي التحكمات الثلاثة التي يقدمها كل محرر صور، ومن السهل الخلط بينها. الثلاثة تفتّح الصورة أو تعتّمها، لكن بطرق مختلفة.</p>\n<p>استخدام الخاطئ منها يعطي نتيجة أسوأ. الصورة التي تحتاج تباينًا ستبدو مغسولة إذا فتّحتها فقط، والصورة التي تحتاج سطوعًا ستبدو قاسية إذا أضفت تباينًا فقط.</p>\n<p>يشرح هذا المقال كل تحكم، وكيف تختلف، وكيف تتفاعل، وأيها تلجأ إليه في كل موقف. إنه أساس كل تحرير صور آخر ستقوم به.</p>\n<p>ولتشعر بالفرق بين التحكمات الثلاثة، يمكنك تحريكها مجانًا في المتصفح مع <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصورة</a> وترى مباشرة كيف يستجيب كل منها على صورتك.</p>\n<h2 id=\"what-each-does\">ماذا يفعل كل تحكم</h2>\n<p>السطوع يزيح كل بكسل نحو الأبيض أو الأسود بشكل موحد عبر الصورة كلها. إنه أبسط تحكم، ويصلح صورة داكنة أو فاتحة بشكل عام.</p>\n<p>التعريض يغيّر كمية الضوء التي يبدو أن الصورة التقطتها. يؤثر في الأضواء والظلال بشكل مختلف، محافظًا على تفاصيل أكثر في الطرفين من السطوع. أما التباين فيمد أو يضغط المسافة بين أظلم أجزاء الصورة وأفتحها.</p>\n<h2 id=\"brightness-explained\">السطوع، مشروح ببساطة</h2>\n<p>السطوع إزاحة موحدة. كل بكسل يفتّح أو يعتّم بالمقدار نفسه، فتبقى الفروق النسبية بين الأشياء كما هي.</p>\n<p>إنه أسرع إصلاح لصورة داكنة أو فاتحة جدًا بشكل عام. لقطة داخلية داكنة مفتّحة 15 بالمئة تصبح مرئية، والتغيير متوقع. وضعف السطوع في الطرفين: دفعه كثيرًا يغسل الأضواء ويحوّل المناطق الفاتحة إلى أبيض بلا ملامح.</p>\n<h2 id=\"exposure-explained\">التعريض، مشروح ببساطة</h2>\n<p>التعريض يحاكي إعداد الكاميرا الذي يحمل الاسم نفسه. في الكاميرا، التعريض هو كمية الضوء التي تصل إلى المستشعر، وفي المحرر يحاكي تغيير تلك الكمية.</p>\n<p>بخلاف السطوع، يعامل التعريض النطاق اللوني بشكل غير متساوٍ. تأثيره أقوى في النغمات الوسطى وأنعم في الأضواء والظلال القصوى، ما يحافظ على تفاصيل أكثر. وهذا يجعله خيارًا أفضل عندما تهم الأضواء، مثل سماء ساطعة تحافظ على شكلها.</p>\n<h2 id=\"contrast-explained\">التباين، مشروح ببساطة</h2>\n<p>التباين يتعلق بالفرق. الصورة عالية التباين فيها سواد عميق وبياض ساطع بفجوة قوية بينهما، بينما منخفضة التباين تجمع كل شيء معًا في الوسط.</p>\n<p>رفع التباين يجعل الداكن أظلم والفاتح أفتح. يضيف قوة وعمقًا لصورة مسطحة، لكنه قد يسحق الظلال إلى أسود ويقص الأضواء إلى أبيض. وخفضه يفعل العكس: ينعّم الصورة، وهذا يناسب الصور الضبابية والبورتريه الناعم.</p>\n<h2 id=\"how-they-interact\">كيف تتفاعل التحكمات الثلاثة</h2>\n<p>السطوع والتباين يتفاعلان مباشرة. تفتيح صورة يجعلها تبدو مسطحة غالبًا، لأن رفع الظلال يقلل الفجوة بين الداكن والفاتح، وإضافة التباين تستعيدها.</p>\n<p>والتعريض والتباين يتفاعلان أيضًا. زيادة التعريض قد تغسل الأضواء، بينما زيادة التباين تعيد العمق الذي أزاله تغيير التعريض. والنمط الشائع هو ضبط السطوع أولًا ثم التباين، لأن السطوع يثبت المستوى العام والتباين يضبط المدى حوله.</p>\n<h2 id=\"when-to-use-brightness\">متى تستخدم السطوع</h2>\n<p>استخدم السطوع عندما تكون الصورة كلها داكنة جدًا أو فاتحة جدًا. لقطة داخلية داكنة أو منظر باهت بسماء غائمة أو مسح معتم يحتاج دفعة عامة.</p>\n<p>السطوع هو الخيار الصحيح أيضًا للقطات الشاشة والمستندات. يجب أن يُقرأ النص، والدفعة الموحدة تجعل المسح الداكن واضحًا دون تغيير طابعه. ولصورة ستكون خلف نص، السطوع هو الأداة لتعتيمها.</p>\n<h2 id=\"when-to-use-exposure\">متى تستخدم التعريض</h2>\n<p>استخدم التعريض عندما تهم الأضواء. منظر بسماء مفصلة أو بورتريه بأضواء ساطعة على الجلد أو صورة منتج بأسطح لامعة تحتاج اللمسة الأنعم.</p>\n<p>التعريض هو الخيار الأفضل لصورة منحرفة قليلًا. تغيير تعريض صغير يصحح المستوى دون الغسل القاسي الذي قد تسببه حركة سطوع كبيرة. ولصورة ملتقطة في شمس قوية، التعريض هو التحكم الآمن لأنه يحافظ على المناطق الفاتحة بينما يرفع الظلال.</p>\n<h2 id=\"when-to-use-contrast\">متى تستخدم التباين</h2>\n<p>استخدم التباين عندما تبدو الصورة مسطحة ورمادية، حتى لو كان سطوعها العام جيدًا. المشكلة هي المدى لا المستوى، والتباين وحده يصلح المدى.</p>\n<p>التباين هو الخيار الصحيح للصور الضبابية والمناظر بالضباب واللقطات الداخلية الباهتة. دفعة صغيرة تضيف قوة وتجعل الصورة تبدو صلبة مجددًا. واستخدم تباينًا سالبًا لتنعيم صورة قاسية، مثل بورتريهات الظهيرة بظلال قوية.</p>\n<h2 id=\"order-of-edits\">الترتيب الصحيح: السطوع ثم التباين</h2>\n<p>ابدأ بالسطوع لأنه يثبت المستوى العام. الصورة الداكنة جدًا تحتاج إلى رفع قبل أن تستطيع الحكم على تباينها، والصورة الفاتحة جدًا تحتاج إلى تعتيم أولًا.</p>\n<p>ثم اضبط التباين. مع تثبيت المستوى، تستطيع رؤية هل الصورة مسطحة أم قوية، وحركة تباين صغيرة تصلح المدى. وأخيرًا، راجع السطوع مجددًا، لأن تغيير التباين قد يجعل الصورة تبدو أظلم أو أفتح. واعمل بخطوات صغيرة في كل مرحلة.</p>\n<h2 id=\"portraits\">البورتريه: أي تحكم يهم أكثر</h2>\n<p>البورتريه يحتاج سطوعًا ناعمًا وتباينًا حذرًا. الوجه الداكن جدًا يخفي التعبير، لكن الوجه ذو التباين المفرط يبدو قاسيًا ومسنًا.</p>\n<p>ابدأ بدفعة سطوع صغيرة من 10 إلى 15 بالمئة. وراجع درجات الجلد: يجب أن تبدو مضاءة بطبيعية لا كأن فلاشًا أطلق من قريب. وأضف التباين فقط إذا بدا البورتريه مسطحًا، فدفعة صغيرة 10 بالمئة تكفي غالبًا.</p>\n<h2 id=\"landscapes\">المناظر الطبيعية: موازنة السماء والمقدمة</h2>\n<p>المناظر الطبيعية تحتاج غالبًا سطوعًا للمقدمة وضبطًا للسماء. زيادة سطوع موحدة قد تغسل الغيوم بينما تصلح الأرض.</p>\n<p>استخدم زيادة سطوع معتدلة وراجع السماء أولًا. إذا فقدت الغيوم شكلها فقد تجاوزت الحد، والحركة الأصغر هي الإجابة الصحيحة. وأضف تباينًا لاستعادة العمق الذي أزاله التفتيح، فالمنظر بسماء صافية ومقدمة مفصلة يحتاج التحكمين معًا.</p>\n<h2 id=\"screenshots\">لقطات الشاشة والمستندات: السطوع أولًا</h2>\n<p>لقطات الشاشة والمستندات الممسوحة تحتاج سطوعًا أكثر من التباين. الهدف نص مقروء فوق خلفية نظيفة، والدفعة الموحدة تحقق ذلك مباشرة.</p>\n<p>ارفع السطوع حتى يصبح النص واضحًا والخلفية بيضاء. المستند بخلفية بيضاء نظيفة ونص داكن سهل القراءة والطباعة. وأضف تباينًا فقط إذا بدا النص رماديًا بعد التفتيح، فدفعة صغيرة تعتّم الحروف وتحدد الحواف.</p>\n<h2 id=\"text-over-photos\">النص فوق الصور: التباين هو المفتاح</h2>\n<p>النص فوق صورة يحتاج تباينًا بين الحروف والخلفية. الصورة الفاتحة مع نص أبيض تفشل، والصورة الداكنة مع نص أسود تفشل بالقدر نفسه.</p>\n<p>عتّم الصورة خلف النص لتُقرأ الحروف البيضاء. خفض سطوع 20 إلى 30 بالمئة في الصورة كلها ينشئ منطقة داكنة للنص. وبدلًا من ذلك، ارفع تباين الصورة لفصل المناطق الفاتحة والداكنة. وللدليل الكامل للنص المقروء، اقرأ <a href=\"/ar/blog/tabayun-wa-qiraat-an-nass-fawq-as-suwar/\">التباين للمقروئية: النص فوق الصور</a>.</p>\n<h2 id=\"common-confusions\">الالتباسات الشائعة بين الثلاثة</h2>\n<p>الالتباس الأكثر شيوعًا هو معاملة السطوع والتباين كشيء واحد. ليسا كذلك: السطوع يحرك المستوى، بينما التباين يغيّر المدى، وقد تحتاج الصورة أحدهما دون الآخر.</p>\n<p>من الالتباسات الأخرى استخدام السطوع لإصلاح صورة مسطحة. الصورة المسطحة في المستوى الصحيح أصلًا، فتفتيحها يجعلها أفتح وأكثر تسطحًا لا أفضل. والحل هو التشخيص قبل التحرير: اسأل هل الصورة داكنة جدًا أم مسطحة جدًا أم كلاهما، واختر التحكم المطابق للتشخيص.</p>\n<h2 id=\"testing-combinations\">كيف تختبر التركيبات قبل التأكيد</h2>\n<p>اختبر السطوع والتباين معًا بخطوات صغيرة. دفعة سطوع 10 بالمئة مع زيادة تباين 10 بالمئة نقطة بداية جيدة لصورة داكنة ومسطحة.</p>\n<p>استخدم عرض المقارنة بعد كل تغيير. العرض المنقسم يظهر بالضبط ما فعله كل ضبط، فتستطيع التوقف عندما تبدو الصورة جيدة. وراجع الأضواء والظلال منفصلين، فالأضواء تُقص أولًا مع السطوع والظلال تُسحق أولًا مع التباين.</p>\n<h2 id=\"cheat-sheet\">ورقة الغش لقرارات سريعة</h2>\n<p>استخدم السطوع عندما تكون الصورة كلها داكنة جدًا أو فاتحة جدًا. إنه أسرع إصلاح لمشكلة مستوى عامة، ويناسب لقطات الشاشة والمستندات.</p>\n<p>استخدم التعريض عندما تهم الأضواء ويقدمه محررك. واستخدم التباين عندما تبدو الصورة مسطحة ورمادية حتى لو كان سطوعها جيدًا. واستخدم السطوع أولًا ثم التباين عندما تحتاج الصورة كليهما، لأن الترتيب مهم.</p>\n<h2 id=\"three-controls-for-thumbnails\">السطوع والتعريض والتباين للصور المصغرة</h2>\n<p>الصور المصغرة للفيديو تُعرض صغيرة، فتحتاج مستويات قوية وتباينًا واضحًا. الصورة المصغرة الداكنة والمسطحة تختفي في الخلاصة، بينما الفاتحة والقوية تجذب العين.</p>\n<p>فتّح الصورة المصغرة أكثر قليلًا مما تفعل مع صورة كاملة. الحجم الصغير يخفي الدقة، فالصورة الفاتحة والمضاءة جيدًا تعمل أفضل من صورة الأجواء. وأضف تباينًا لفصل الموضوع عن الخلفية، واختبر الصورة المصغرة بحجمها الحقيقي قبل النشر.</p>\n<p>للخطوات العملية، راجع <a href=\"/ar/blog/kayfiyya-taadil-sutoo-as-sura/\">كيف تضبط سطوع صورة</a> و<a href=\"/ar/blog/kayfiyya-taadil-tabayun-as-sura/\">كيف تضبط تباين صورة</a>. وللأدلة الكاملة، اقرأ <a href=\"/ar/blog/dalil-muharrir-sutoo-as-suwar/\">محرر سطوع الصورة: الدليل الكامل</a> و<a href=\"/ar/blog/dalil-muharrir-tabayun-as-suwar/\">محرر تباين الصور: الدليل الكامل</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الفرق بين السطوع والتباين؟","answer":"السطوع يزيح كل بكسل نحو الأبيض أو الأسود بشكل موحد، محركًا النطاق اللوني كله لأعلى أو لأسفل. التباين يمد أو يضغط الفجوة بين أظلم الأجزاء وأفتحها. الصورة قد تحتاج أحدهما دون الآخر."},{"question":"هل التعريض هو نفسه السطوع؟","answer":"لا، رغم أنهما يبدوان متشابهين. التعريض يؤثر في الأضواء والظلال بشكل مختلف، محافظًا على تفاصيل أكثر في الطرفين، بينما السطوع يحرك كل شيء بشكل موحد. التعريض أنعم مع الأضواء الساطعة."},{"question":"هل أضبط السطوع أم التباين أولًا؟","answer":"السطوع أولًا ثم التباين. السطوع يثبت المستوى العام، والتباين يضبط المدى حول ذلك المستوى. وبعد تغيير التباين، راجع السطوع مجددًا، لأن الصورة قد تبدو أظلم أو أفتح."},{"question":"لماذا تبدو صورتي مسطحة بعد تفتيحها؟","answer":"التفتيح يرفع الظلال ويقلل الفجوة بين الداكن والفاتح، ما يسطح الصورة. أضف دفعة تباين صغيرة بعدها لاستعادة العمق. دفعة سطوع 10 بالمئة مع زيادة تباين 10 بالمئة نقطة بداية جيدة."},{"question":"هل يستطيع التباين إصلاح صورة داكنة جدًا؟","answer":"لا، فالتباين يغيّر المدى لا المستوى، فالصورة الداكنة ذات التباين العالي تبقى داكنة، فقط بظلال أعمق. فتّح الصورة أولًا لإصلاح المستوى، ثم أضف تباينًا إذا بدت مسطحة."},{"question":"أي تحكم أستخدم لصورة منظر ضبابي؟","answer":"التباين عادة، مع دفعة سطوع صغيرة أولًا. الضباب يسطح النطاق اللوني، فزيادة التباين تستعيد العمق. ابدأ بسطوع 10 بالمئة إذا كانت الصورة داكنة، ثم ارفع التباين 10 إلى 15 بالمئة."}];
